look.customCSS:
/* ───── 雨天窗边 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/90px 120px repeat,linear-gradient(180deg,#C9D6E0,#DCE5EC 40%,#E6ECF1) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一截白窗框，下沿一条木窗台 */
[data-wk="chathead"]{background:#F7F9FA !important;border-bottom:none !important;box-shadow:0 4px 0 #B79B7E,0 7px 10px rgba(60,74,87,.12) !important}
[data-wk="headink"],[data-wk="headink"] *{color:#3C4A57 !important}
[data-wk="headdim"]{color:#8A9AA8 !important;white-space:nowrap !important}
[data-wk="chatback"] svg{stroke:#3C4A57 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/21px no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PGNpcmNsZSBjeD0nNScgY3k9JzEyJyByPScxLjUnIGZpbGw9JyMzQzRBNTcnLz48Y2lyY2xlIGN4PScxMicgY3k9JzEyJyByPScxLjUnIGZpbGw9JyMzQzRBNTcnLz48Y2lyY2xlIGN4PScxOScgY3k9JzEyJyByPScxLjUnIGZpbGw9JyMzQzRBNTcnLz48L3N2Zz4=") center/21px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆，一圈白窗框 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 2px #F7F9FA,0 0 0 3.2px #8EA8BC !important}

/* 我的话：起雾的玻璃，右上挂两颗水珠 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;color:#3C4A57 !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(160deg,rgba(255,255,255,.55),rgba(255,255,255,0) 45%),#B9CCDA !important;border:1.2px solid #8EA8BC !important;border-radius:16px 16px 4px 16px !important;box-shadow:inset 0 1px 0 rgba(255,255,255,.7) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;right:6px !important;top:-7px !important;left:auto !important;bottom:auto !important;width:24px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:none !important}
/* 他的话：窗边一张白便条，左上斜着一道窗框的影子 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(125deg,rgba(142,168,188,.16) 0 14px,transparent 14px),#FBFCFD !important;border:1.2px solid #8EA8BC !important;border-radius:16px 16px 16px 4px !important;box-shadow:0 2px 6px rgba(60,74,87,.10) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before,[data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:none !important}

/* 时间：雾里的一行小字，两边一短横 */
[data-wk="time"] > span{min-width:150px !important;background:transparent !important;border:none !important;color:#8A9AA8 !important;font-size:11px !important;letter-spacing:.12em !important}
[data-wk="time"] > span::before{content:"— " !important}
[data-wk="time"] > span::after{content:" —" !important}
/* 已读：一颗小水滴；已送达一行小字 */
[data-wk="meta"]{color:#8A9AA8 !important;font-size:10.5px !important}
[data-wk="meta"][data-read="1"]{font-size:0 !important;width:11px !important;height:14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"] *{opacity:0 !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FBFCFD !important;border:1.2px solid #8EA8BC !important;border-radius:16px 16px 16px 4px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#6F93B0 !important}

/* 动描：像写在起雾玻璃上的字——没有框，左边一道往下流的水痕 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{background:transparent !important;border:none !important;box-shadow:none !important;color:#3C4A57 !important;opacity:.72 !important;font-style:italic !important;font-size:13px !important;padding-left:14px !important;border-left:2px solid transparent !important;border-image:linear-gradient(180deg,#6F93B0,rgba(111,147,176,0)) 1 !important;border-radius:0 !important}
/* 系统提示：不带框的一行小字，前面一把小伞 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#8A9AA8 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.06em !important}
[data-wk="sysnotetext"]::before{content:"☂ " !important}

/* 底栏：白窗框＋上沿一条窗台，左发送右回复 */
[data-wk="composer"]{background:#F7F9FA !important;border-top:none !important;box-shadow:0 -4px 0 #B79B7E !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#EEF3F6 !important;border:1.2px solid #8EA8BC !important;border-radius:14px !important;color:#3C4A57 !important}
[data-wk="chatinput"]::placeholder{color:#8A9AA8 !important}
[data-wk="chatplus"],[data-wk="send"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/23px no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{position:relative !important;width:64px !important;min-width:64px !important;height:34px !important;border:none !important;border-radius:17px !important;background:#6F93B0 !important;box-shadow:inset 0 1px 0 rgba(255,255,255,.35) !important}
[data-wk="chatreply"]::before{content:"回复" !important;position:absolute !important;inset:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;color:#fff !important;font-size:13px !important;letter-spacing:.15em !important;padding-left:14px !important}
[data-wk="chatreply"]::after{content:"" !important;position:absolute !important;left:9px !important;top:50% !important;width:14px !important;height:14px !important;margin-top:-7px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
